INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-neck-flexion-with-band', 'Neck Flexion with Band', 'Flexión de cuello con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['neck']::text[], ARRAY[]::text[], 'Anchor a band behind you and loop it around your head. Tuck your chin and bring your head forward against the band. Return slowly.', 'Ancla una banda detrás de ti y colócala alrededor de la cabeza. Lleva la barbilla al pecho tirando contra la banda. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Neck Flexion with Band'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-neck-extension-with-band', 'Neck Extension with Band', 'Extensión de cuello con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['neck']::text[], ARRAY['traps']::text[], 'Anchor a band in front of you and loop it around the back of your head. Extend your neck backward against the band. Return with control.', 'Ancla una banda delante de ti y colócala tras la cabeza. Extiende el cuello hacia atrás contra la banda. Vuelve con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Neck Extension with Band'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-neck-lateral-flexion-with-band', 'Neck Lateral Flexion with Band', 'Flexión lateral de cuello con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['neck']::text[], ARRAY['traps']::text[], 'Anchor a band at head height to your side. Tilt your head away from the anchor against the band. Return slowly and switch sides.', 'Ancla una banda a la altura de la cabeza a un lado. Inclina la cabeza alejándote del anclaje contra la banda. Vuelve despacio y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Neck Lateral Flexion with Band'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-neck-rotation-with-band', 'Neck Rotation with Band', 'Rotación de cuello con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['neck']::text[], ARRAY[]::text[], 'Anchor a band at head height to your side and loop it around your head. Rotate your head away from the anchor keeping shoulders still. Return slowly.', 'Ancla una banda a la altura de la cabeza y pásala por la cabeza. Gira la cabeza alejándote del anclaje sin mover los hombros. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Neck Rotation with Band'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-manual-resistance-neck-flexion', 'Manual Resistance Neck Flexion', 'Flexión de cuello con resistencia manual', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['neck']::text[], ARRAY[]::text[], 'Place your palm on your forehead. Push your head forward while your hand resists. Hold a few seconds and relax.', 'Coloca la palma en la frente. Empuja la cabeza hacia delante mientras la mano resiste. Mantén unos segundos y relaja.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Manual Resistance Neck Flexion'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-manual-resistance-neck-extension', 'Manual Resistance Neck Extension', 'Extensión de cuello con resistencia manual', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['neck']::text[], ARRAY['traps']::text[], 'Clasp your hands behind your head. Push your head back while your hands resist. Hold a few seconds and relax.', 'Entrelaza las manos detrás de la cabeza. Empuja la cabeza hacia atrás mientras las manos resisten. Mantén unos segundos y relaja.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Manual Resistance Neck Extension'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-manual-resistance-neck-side-flexion', 'Manual Resistance Neck Side Flexion', 'Flexión lateral de cuello con resistencia manual', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['neck']::text[], ARRAY[]::text[], 'Place one palm on the side of your head. Push your head sideways against your hand. Hold a few seconds and switch sides.', 'Coloca una palma en el lateral de la cabeza. Empuja la cabeza hacia el lado contra la mano. Mantén unos segundos y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Manual Resistance Neck Side Flexion'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-neck-harness-extension', 'Neck Harness Extension', 'Extensión de cuello con arnés', 'strength', 'intermediate', ARRAY['other']::text[], ARRAY['neck']::text[], ARRAY['traps']::text[], 'Fit a head harness and attach a light plate. Bend forward at the hips with a flat back. Extend your neck up and lower slowly.', 'Colócate un arnés de cabeza con un disco ligero. Inclínate desde la cadera con la espalda recta. Extiende el cuello hacia arriba y baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Neck Harness Extension'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-weighted-neck-extension-on-bench', 'Weighted Neck Extension on Bench', 'Extensión de cuello con peso tumbado en banco', 'strength', 'intermediate', ARRAY['other']::text[], ARRAY['neck']::text[], ARRAY['traps']::text[], 'Lie face down on a bench with your head past the edge and a plate on the back of the head. Lower your head slowly. Raise it back to neutral.', 'Túmbate boca abajo en un banco con la cabeza fuera del borde y un disco en la nuca. Baja la cabeza despacio. Vuelve a la posición neutra.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Weighted Neck Extension on Bench'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-weighted-neck-lateral-flexion', 'Weighted Neck Lateral Flexion', 'Flexión lateral de cuello con peso', 'strength', 'intermediate', ARRAY['other']::text[], ARRAY['neck']::text[], ARRAY[]::text[], 'Lie on your side on a bench with your head past the edge and a light plate on the temple. Lower your head slightly. Raise it back to neutral and switch sides.', 'Túmbate de lado en un banco con la cabeza fuera del borde y un disco ligero en la sien. Baja la cabeza un poco. Vuelve a neutro y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Weighted Neck Lateral Flexion'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-neck-bridge', 'Neck Bridge', 'Puente de cuello', 'strength', 'expert', ARRAY['body only']::text[], ARRAY['neck']::text[], ARRAY['traps','lower back']::text[], 'Lie on your back with knees bent and place a mat under your head. Lift your hips and rest on the top of your head. Hold briefly and lower with control.', 'Túmbate boca arriba con las rodillas flexionadas y una esterilla bajo la cabeza. Eleva la cadera y apóyate en la parte superior de la cabeza. Mantén brevemente y baja con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Neck Bridge'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-chin-tuck', 'Chin Tuck', 'Retracción de barbilla', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['neck']::text[], ARRAY[]::text[], 'Sit or stand tall with eyes forward. Draw your chin straight back to make a double chin. Hold for a few seconds and release.', 'Siéntate o ponte de pie con la mirada al frente. Lleva la barbilla recta hacia atrás. Mantén unos segundos y suelta.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Chin Tuck'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-isometric-neck-rotation', 'Isometric Neck Rotation', 'Isometría de rotación de cuello', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['neck']::text[], ARRAY[]::text[], 'Place your palm on your cheek. Turn your head into your hand while it resists. Hold a few seconds and switch sides.', 'Coloca la palma en la mejilla. Gira la cabeza contra la mano mientras resiste. Mantén unos segundos y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Isometric Neck Rotation'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-neck-machine-flexion', 'Neck Machine Flexion', 'Flexión de cuello en máquina', 'strength', 'intermediate', ARRAY['machine']::text[], ARRAY['neck']::text[], ARRAY[]::text[], 'Adjust the neck machine and place your forehead against the pad. Flex your neck forward through a short range. Return slowly.', 'Ajusta la máquina de cuello y apoya la frente en el cojín. Flexiona el cuello hacia delante en un rango corto. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Neck Machine Flexion'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-neck-machine-extension', 'Neck Machine Extension', 'Extensión de cuello en máquina', 'strength', 'intermediate', ARRAY['machine']::text[], ARRAY['neck']::text[], ARRAY['traps']::text[], 'Adjust the neck machine and place the back of your head against the pad. Extend your neck backward through a short range. Return slowly.', 'Ajusta la máquina de cuello y apoya la nuca en el cojín. Extiende el cuello hacia atrás en un rango corto. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Neck Machine Extension'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-cable-hip-abduction', 'Cable Hip Abduction', 'Abducción de cadera en polea', 'strength', 'beginner', ARRAY['cable']::text[], ARRAY['abductors']::text[], ARRAY['glutes']::text[], 'Attach an ankle cuff to a low pulley and stand sideways to the stack. Lift the outer leg out to the side. Return slowly without leaning.', 'Fija una tobillera a una polea baja y colócate de lado a la torre. Eleva la pierna exterior hacia el lado. Vuelve despacio sin inclinarte.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Cable Hip Abduction'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-band-lateral-walk', 'Band Lateral Walk', 'Caminata lateral con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['abductors']::text[], ARRAY['glutes']::text[], 'Place a band around your thighs or ankles and bend your knees slightly. Step sideways keeping tension on the band. Take steps in both directions.', 'Coloca una banda en los muslos o tobillos y flexiona un poco las rodillas. Da pasos laterales manteniendo la tensión. Repite en ambas direcciones.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Band Lateral Walk'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-standing-hip-abduction-with-band', 'Standing Hip Abduction with Band', 'Abducción de cadera de pie con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['abductors']::text[], ARRAY['glutes']::text[], 'Loop a band around your ankles and hold a support. Lift one leg out to the side keeping your torso upright. Return slowly.', 'Coloca una banda en los tobillos y apóyate en un soporte. Eleva una pierna hacia el lado con el torso erguido. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Standing Hip Abduction with Band'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-seated-banded-hip-abduction', 'Seated Banded Hip Abduction', 'Abducción de cadera sentado con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['abductors']::text[], ARRAY['glutes']::text[], 'Sit on a bench with a band around your knees. Push your knees apart against the band. Return slowly.', 'Siéntate en un banco con una banda en las rodillas. Separa las rodillas contra la banda. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Seated Banded Hip Abduction'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-glute-bridge-with-band-abduction', 'Glute Bridge with Band Abduction', 'Puente de glúteo con abducción con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['abductors']::text[], ARRAY['glutes']::text[], 'Lie on your back with a band above the knees and feet flat. Lift your hips into a bridge. Press your knees outward against the band and hold.', 'Túmbate boca arriba con una banda sobre las rodillas y los pies apoyados. Eleva la cadera en un puente. Empuja las rodillas hacia fuera contra la banda y mantén.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Glute Bridge with Band Abduction'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-banded-fire-hydrant', 'Banded Fire Hydrant', 'Perro cazador con banda', 'strength', 'intermediate', ARRAY['bands']::text[], ARRAY['abductors']::text[], ARRAY['glutes']::text[], 'Start on hands and knees with a band above the knees. Lift one bent knee out to the side against the band. Lower with control.', 'Empieza a cuatro apoyos con una banda sobre las rodillas. Eleva una rodilla flexionada hacia el lado contra la banda. Baja con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Banded Fire Hydrant'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-lateral-band-squat-walk', 'Lateral Band Squat Walk', 'Caminata lateral en sentadilla con banda', 'strength', 'intermediate', ARRAY['bands']::text[], ARRAY['abductors']::text[], ARRAY['glutes','quadriceps']::text[], 'Place a band above your knees and lower into a quarter squat. Step sideways while staying low. Keep your knees pushed out.', 'Coloca una banda sobre las rodillas y baja a un cuarto de sentadilla. Da pasos laterales manteniéndote abajo. Mantén las rodillas hacia fuera.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Lateral Band Squat Walk'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-side-plank-hip-abduction', 'Side Plank Hip Abduction', 'Plancha lateral con abducción de cadera', 'strength', 'intermediate', ARRAY['body only']::text[], ARRAY['abductors']::text[], ARRAY['abdominals','glutes']::text[], 'Hold a side plank on your forearm. Lift the top leg up and slightly back. Lower with control and switch sides.', 'Mantén una plancha lateral sobre el antebrazo. Eleva la pierna superior arriba y un poco atrás. Baja con control y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Side Plank Hip Abduction'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-ankle-weight-hip-abduction', 'Ankle Weight Hip Abduction', 'Abducción de cadera con tobillera lastrada', 'strength', 'beginner', ARRAY['other']::text[], ARRAY['abductors']::text[], ARRAY['glutes']::text[], 'Strap an ankle weight on and lie on your side. Lift the top leg without rotating the hips. Lower slowly.', 'Colócate una tobillera con peso y túmbate de lado. Eleva la pierna superior sin girar la cadera. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Ankle Weight Hip Abduction'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-lateral-leg-swings', 'Lateral Leg Swings', 'Balanceo lateral de piernas', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['abductors']::text[], ARRAY['adductors']::text[], 'Hold a support and stand sideways to it. Swing the outer leg across your body and out to the side. Keep your torso steady.', 'Apóyate en un soporte colocado a tu lado. Balancea la pierna exterior cruzando el cuerpo y hacia fuera. Mantén el torso estable.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Lateral Leg Swings'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-standing-machine-hip-abduction', 'Standing Machine Hip Abduction', 'Abducción de cadera de pie en máquina', 'strength', 'beginner', ARRAY['machine']::text[], ARRAY['abductors']::text[], ARRAY['glutes']::text[], 'Stand facing the machine with the pad against your outer thigh. Push the leg out to the side. Return slowly.', 'Colócate de pie frente a la máquina con el cojín en el muslo exterior. Empuja la pierna hacia el lado. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Standing Machine Hip Abduction'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-seated-ball-squeeze', 'Seated Ball Squeeze', 'Apretón de balón sentado', 'strength', 'beginner', ARRAY['exercise ball']::text[], ARRAY['adductors']::text[], ARRAY[]::text[], 'Sit tall with a ball between your knees. Squeeze the ball firmly. Hold briefly and release.', 'Siéntate erguido con un balón entre las rodillas. Aprieta el balón con fuerza. Mantén brevemente y suelta.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Seated Ball Squeeze'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-lying-adductor-ball-squeeze', 'Lying Adductor Ball Squeeze', 'Apretón de aductores con balón tumbado', 'strength', 'beginner', ARRAY['exercise ball']::text[], ARRAY['adductors']::text[], ARRAY['abdominals']::text[], 'Lie on your back with knees bent and a ball between them. Squeeze the ball and hold. Release slowly.', 'Túmbate boca arriba con las rodillas flexionadas y un balón entre ellas. Aprieta el balón y mantén. Suelta despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Lying Adductor Ball Squeeze'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-short-lever-copenhagen-plank', 'Short Lever Copenhagen Plank', 'Plancha Copenhague de palanca corta', 'strength', 'intermediate', ARRAY['body only']::text[], ARRAY['adductors']::text[], ARRAY['abdominals']::text[], 'Hold a side plank with your top knee resting on a bench. Lift your hips from the floor. Hold and switch sides.', 'Mantén una plancha lateral con la rodilla superior sobre un banco. Eleva la cadera del suelo. Mantén y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Short Lever Copenhagen Plank'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-side-lying-hip-adduction', 'Side-Lying Hip Adduction', 'Aducción de cadera tumbado de lado', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['adductors']::text[], ARRAY[]::text[], 'Lie on your side with the top leg bent and its foot in front. Lift the bottom leg straight up. Lower slowly.', 'Túmbate de lado con la pierna superior flexionada y el pie por delante. Eleva la pierna inferior estirada. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Side-Lying Hip Adduction'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-dumbbell-sumo-squat', 'Dumbbell Sumo Squat', 'Sentadilla sumo con mancuerna', 'strength', 'beginner', ARRAY['dumbbell']::text[], ARRAY['adductors']::text[], ARRAY['glutes','quadriceps']::text[], 'Hold one dumbbell vertically between your legs with feet wide. Squat down with a tall chest. Drive up through the heels.', 'Sujeta una mancuerna en vertical entre las piernas con los pies separados. Baja con el pecho alto. Sube empujando con los talones.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Dumbbell Sumo Squat'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-cossack-squat', 'Cossack Squat', 'Sentadilla cosaca', 'strength', 'intermediate', ARRAY['body only']::text[], ARRAY['adductors']::text[], ARRAY['glutes','quadriceps']::text[], 'Stand with a very wide stance. Shift your weight to one side and squat deeply while the other leg stays straight. Push back to the center and alternate.', 'Ponte de pie con una postura muy ancha. Carga el peso en un lado y baja profundo con la otra pierna estirada. Empuja de vuelta al centro y alterna.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Cossack Squat'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-kettlebell-cossack-squat', 'Kettlebell Cossack Squat', 'Sentadilla cosaca con pesa rusa', 'strength', 'intermediate', ARRAY['kettlebells']::text[], ARRAY['adductors']::text[], ARRAY['glutes','quadriceps']::text[], 'Hold a kettlebell at your chest in a wide stance. Shift to one side and squat deep with the other leg straight. Return and alternate.', 'Sujeta una pesa rusa al pecho con postura ancha. Carga un lado y baja profundo con la otra pierna estirada. Vuelve y alterna.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Kettlebell Cossack Squat'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-seated-straddle-stretch', 'Seated Straddle Stretch', 'Estiramiento sentado con piernas abiertas', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['adductors']::text[], ARRAY['hamstrings']::text[], 'Sit with legs spread wide and knees straight. Walk your hands forward keeping your back long. Hold and breathe.', 'Siéntate con las piernas muy abiertas y rodillas estiradas. Camina con las manos hacia delante con la espalda larga. Mantén y respira.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Seated Straddle Stretch'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-one-arm-dead-hang', 'One-Arm Dead Hang', 'Colgado a una mano', 'strength', 'expert', ARRAY['body only']::text[], ARRAY['forearms']::text[], ARRAY['lats','shoulders']::text[], 'Grip a pull-up bar with one hand. Hang with your shoulder engaged and body still. Hold and switch hands.', 'Agarra una barra con una mano. Cuélgate con el hombro activo y el cuerpo quieto. Mantén y cambia de mano.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('One-Arm Dead Hang'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-towel-dead-hang', 'Towel Dead Hang', 'Colgado con toalla', 'strength', 'intermediate', ARRAY['other']::text[], ARRAY['forearms']::text[], ARRAY['lats']::text[], 'Drape a towel over a pull-up bar and grip both ends. Hang with arms straight. Hold as long as you can.', 'Pasa una toalla sobre una barra y agarra ambos extremos. Cuélgate con los brazos estirados. Mantén el mayor tiempo posible.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Towel Dead Hang'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-farmer-s-hold', 'Farmer''s Hold', 'Sostén del granjero', 'strength', 'beginner', ARRAY['dumbbell']::text[], ARRAY['forearms']::text[], ARRAY['traps']::text[], 'Pick up a heavy dumbbell in each hand. Stand tall with shoulders back. Hold as long as you can.', 'Coge una mancuerna pesada en cada mano. Ponte erguido con los hombros atrás. Mantén el mayor tiempo posible.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Farmer''s Hold'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-plate-pinch-carry', 'Plate Pinch Carry', 'Paseo con pellizco de discos', 'strength', 'intermediate', ARRAY['other']::text[], ARRAY['forearms']::text[], ARRAY['traps']::text[], 'Pinch two smooth plates together with each hand. Walk a set distance keeping posture tall. Lower them under control.', 'Pellizca dos discos lisos juntos con cada mano. Camina una distancia fija con postura erguida. Suéltalos con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Plate Pinch Carry'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-cable-reverse-wrist-curl', 'Cable Reverse Wrist Curl', 'Curl de muñeca inverso en polea', 'strength', 'beginner', ARRAY['cable']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Hold a bar attached to a low pulley with palms down and forearms on a bench. Extend your wrists upward. Lower slowly.', 'Sujeta una barra de polea baja con las palmas hacia abajo y los antebrazos en un banco. Extiende las muñecas hacia arriba. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Cable Reverse Wrist Curl'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-cable-behind-the-back-wrist-curl', 'Cable Behind-the-Back Wrist Curl', 'Curl de muñeca tras la espalda en polea', 'strength', 'beginner', ARRAY['cable']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Stand facing away from a low pulley holding the bar behind you. Curl the bar up with your wrists only. Lower slowly.', 'Colócate de espaldas a una polea baja sujetando la barra detrás de ti. Sube la barra solo con las muñecas. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Cable Behind-the-Back Wrist Curl'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-band-wrist-curl', 'Band Wrist Curl', 'Curl de muñeca con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Hold a band under your foot with palm up and forearm on your thigh. Curl your wrist upward. Lower slowly.', 'Sujeta una banda bajo el pie con la palma hacia arriba y el antebrazo sobre el muslo. Flexiona la muñeca hacia arriba. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Band Wrist Curl'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-band-reverse-wrist-curl', 'Band Reverse Wrist Curl', 'Curl de muñeca inverso con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Hold a band under your foot with palm down and forearm on your thigh. Extend your wrist upward. Lower slowly.', 'Sujeta una banda bajo el pie con la palma hacia abajo y el antebrazo sobre el muslo. Extiende la muñeca hacia arriba. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Band Reverse Wrist Curl'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-dumbbell-radial-deviation', 'Dumbbell Radial Deviation', 'Desviación radial con mancuerna', 'strength', 'beginner', ARRAY['dumbbell']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Hold a dumbbell by one end with your thumb up. Raise the weight by tilting your wrist upward. Lower slowly.', 'Sujeta una mancuerna por un extremo con el pulgar arriba. Sube el peso inclinando la muñeca hacia arriba. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Dumbbell Radial Deviation'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-dumbbell-ulnar-deviation', 'Dumbbell Ulnar Deviation', 'Desviación ulnar con mancuerna', 'strength', 'beginner', ARRAY['dumbbell']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Hold a dumbbell by one end with your thumb up and the weight in front. Lower the weight by tilting your wrist down. Lift back with control.', 'Sujeta una mancuerna por un extremo con el pulgar arriba y el peso delante. Baja el peso inclinando la muñeca. Sube con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Dumbbell Ulnar Deviation'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-rice-bucket-grip', 'Rice Bucket Grip', 'Ejercicio de cubo de arroz', 'strength', 'beginner', ARRAY['other']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Fill a bucket with rice and push your hands inside. Open, close and twist your hands against the resistance. Work for a set time.', 'Llena un cubo de arroz y mete las manos. Abre, cierra y gira las manos contra la resistencia. Trabaja durante un tiempo fijo.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Rice Bucket Grip'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-hand-gripper-squeeze', 'Hand Gripper Squeeze', 'Apretón con pinza de agarre', 'strength', 'beginner', ARRAY['other']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Hold a hand gripper in your palm. Squeeze the handles together fully. Release slowly.', 'Sujeta una pinza de agarre en la palma. Cierra las asas por completo. Suelta despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Hand Gripper Squeeze'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-tennis-ball-squeeze', 'Tennis Ball Squeeze', 'Apretón de pelota de tenis', 'strength', 'beginner', ARRAY['other']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Hold a tennis ball in your hand. Squeeze it firmly for a few seconds. Release and repeat.', 'Sujeta una pelota de tenis en la mano. Aprieta con fuerza unos segundos. Suelta y repite.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Tennis Ball Squeeze'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-towel-wring', 'Towel Wring', 'Retorcer toalla', 'strength', 'beginner', ARRAY['other']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Hold a rolled towel with both hands. Twist your hands in opposite directions as if wringing it. Switch the direction.', 'Sujeta una toalla enrollada con ambas manos. Gira las manos en sentidos opuestos como si la escurrieras. Cambia de sentido.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Towel Wring'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-finger-extension-with-band', 'Finger Extension with Band', 'Extensión de dedos con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Place a rubber band around your fingers and thumb. Open your fingers against the band. Close slowly.', 'Coloca una goma elástica alrededor de los dedos y el pulgar. Abre los dedos contra la goma. Cierra despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Finger Extension with Band'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-barbell-static-hold', 'Barbell Static Hold', 'Sostén estático de barra', 'strength', 'beginner', ARRAY['barbell']::text[], ARRAY['forearms']::text[], ARRAY['traps']::text[], 'Deadlift a barbell and stand tall. Hold it with a firm grip without shrugging. Lower it under control.', 'Levanta una barra del suelo y ponte erguido. Sostenla con agarre firme sin encoger los hombros. Bájala con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Barbell Static Hold'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-wrist-flexor-stretch', 'Wrist Flexor Stretch', 'Estiramiento de flexores de muñeca', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Extend one arm with the palm facing up. Pull your fingers back gently with the other hand. Hold and switch.', 'Extiende un brazo con la palma hacia arriba. Tira suavemente de los dedos hacia atrás con la otra mano. Mantén y cambia.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Wrist Flexor Stretch'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-wrist-extensor-stretch', 'Wrist Extensor Stretch', 'Estiramiento de extensores de muñeca', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Extend one arm with the palm facing down. Pull your fingers down gently with the other hand. Hold and switch.', 'Extiende un brazo con la palma hacia abajo. Tira suavemente de los dedos hacia abajo con la otra mano. Mantén y cambia.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Wrist Extensor Stretch'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-prayer-stretch', 'Prayer Stretch', 'Estiramiento en oración', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Press your palms together in front of your chest. Lower your hands slowly toward your waist keeping palms together. Hold at a mild stretch.', 'Junta las palmas frente al pecho. Baja las manos despacio hacia la cintura manteniendo las palmas juntas. Mantén en un estiramiento suave.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Prayer Stretch'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-hammer-pronation-and-supination', 'Hammer Pronation and Supination', 'Pronación y supinación con martillo', 'strength', 'beginner', ARRAY['other']::text[], ARRAY['forearms']::text[], ARRAY[]::text[], 'Hold a hammer near the end of the handle with your forearm supported. Rotate your forearm palm up then palm down. Repeat slowly.', 'Sujeta un martillo por el extremo del mango con el antebrazo apoyado. Gira el antebrazo palma arriba y luego abajo. Repite despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Hammer Pronation and Supination'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-weighted-back-extension', 'Weighted Back Extension', 'Extensión de espalda con peso', 'strength', 'intermediate', ARRAY['other']::text[], ARRAY['lower back']::text[], ARRAY['glutes','hamstrings']::text[], 'Set up on a back extension bench holding a plate to your chest. Lower your torso with a neutral spine. Raise until your body is in line.', 'Colócate en un banco de extensiones sujetando un disco al pecho. Baja el torso con la columna neutra. Sube hasta alinear el cuerpo.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Weighted Back Extension'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-machine-back-extension', 'Machine Back Extension', 'Extensión de espalda en máquina', 'strength', 'beginner', ARRAY['machine']::text[], ARRAY['lower back']::text[], ARRAY['glutes']::text[], 'Sit in the machine with the pad against your upper back. Extend your torso backward. Return slowly.', 'Siéntate en la máquina con el cojín en la parte alta de la espalda. Extiende el torso hacia atrás. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Machine Back Extension'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-barbell-good-morning', 'Barbell Good Morning', 'Buenos días con barra', 'strength', 'intermediate', ARRAY['barbell']::text[], ARRAY['lower back']::text[], ARRAY['hamstrings','glutes']::text[], 'Place a barbell on your upper back and soften your knees. Hinge at the hips until your torso is near parallel. Drive hips forward to stand.', 'Coloca una barra en la parte alta de la espalda y flexiona un poco las rodillas. Inclínate desde la cadera hasta que el torso quede casi paralelo. Lleva la cadera adelante para subir.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Barbell Good Morning'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-dumbbell-good-morning', 'Dumbbell Good Morning', 'Buenos días con mancuerna', 'strength', 'beginner', ARRAY['dumbbell']::text[], ARRAY['lower back']::text[], ARRAY['hamstrings','glutes']::text[], 'Hold a dumbbell at your chest. Hinge at the hips with a flat back. Drive hips forward to stand.', 'Sujeta una mancuerna al pecho. Inclínate desde la cadera con la espalda recta. Lleva la cadera adelante para subir.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Dumbbell Good Morning'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-jefferson-curl', 'Jefferson Curl', 'Curl Jefferson', 'strength', 'expert', ARRAY['barbell']::text[], ARRAY['lower back']::text[], ARRAY['hamstrings']::text[], 'Stand on a platform holding a light barbell. Slowly roll your spine forward one vertebra at a time. Reverse the movement to stand.', 'Ponte sobre una plataforma con una barra ligera. Enrolla la columna hacia delante vértebra a vértebra. Invierte el movimiento para subir.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Jefferson Curl'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-prone-cobra', 'Prone Cobra', 'Cobra boca abajo', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['lower back']::text[], ARRAY['glutes','traps']::text[], 'Lie face down with arms by your sides. Lift your chest and arms off the floor squeezing your back. Hold and lower.', 'Túmbate boca abajo con los brazos a los lados. Eleva el pecho y los brazos del suelo apretando la espalda. Mantén y baja.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Prone Cobra'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-swimmers', 'Swimmers', 'Nadador en el suelo', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['lower back']::text[], ARRAY['glutes','shoulders']::text[], 'Lie face down with arms extended overhead. Lift opposite arm and leg and alternate in a flutter motion. Keep the neck neutral.', 'Túmbate boca abajo con los brazos extendidos sobre la cabeza. Eleva brazo y pierna contrarios y alterna con un aleteo. Mantén el cuello neutro.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Swimmers'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-alternating-superman', 'Alternating Superman', 'Superman alterno', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['lower back']::text[], ARRAY['glutes']::text[], 'Lie face down with arms extended. Lift one arm and the opposite leg. Lower and switch sides.', 'Túmbate boca abajo con los brazos extendidos. Eleva un brazo y la pierna contraria. Baja y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Alternating Superman'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-child-s-pose-lateral-reach', 'Child''s Pose Lateral Reach', 'Postura del niño con alcance lateral', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['lower back']::text[], ARRAY['lats']::text[], 'Sit back into child''s pose with arms extended. Walk both hands to one side. Hold and switch sides.', 'Siéntate atrás en la postura del niño con los brazos extendidos. Lleva ambas manos hacia un lado. Mantén y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Child''s Pose Lateral Reach'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-supine-spinal-twist', 'Supine Spinal Twist', 'Torsión espinal tumbado', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['lower back']::text[], ARRAY['glutes']::text[], 'Lie on your back with arms out to the sides. Drop both bent knees to one side. Hold and switch sides.', 'Túmbate boca arriba con los brazos abiertos. Deja caer ambas rodillas flexionadas hacia un lado. Mantén y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Supine Spinal Twist'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-seated-spinal-twist', 'Seated Spinal Twist', 'Torsión espinal sentado', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['lower back']::text[], ARRAY['glutes']::text[], 'Sit with one leg crossed over the other. Rotate your torso toward the bent knee using your elbow. Hold and switch sides.', 'Siéntate con una pierna cruzada sobre la otra. Gira el torso hacia la rodilla flexionada ayudándote del codo. Mantén y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Seated Spinal Twist'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-mcgill-curl-up', 'McGill Curl-Up', 'Curl-up de McGill', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['lower back']::text[], ARRAY['abdominals']::text[], 'Lie on your back with one knee bent and hands under your lower back. Lift your head and shoulders slightly. Hold and lower.', 'Túmbate boca arriba con una rodilla flexionada y las manos bajo la zona lumbar. Eleva ligeramente cabeza y hombros. Mantén y baja.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('McGill Curl-Up'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-suitcase-deadlift', 'Suitcase Deadlift', 'Peso muerto de maleta', 'strength', 'intermediate', ARRAY['dumbbell']::text[], ARRAY['lower back']::text[], ARRAY['glutes','forearms']::text[], 'Stand beside a dumbbell and grip it. Stand up keeping your torso from leaning. Lower under control.', 'Ponte junto a una mancuerna y agárrala. Levántate sin inclinar el torso. Baja con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Suitcase Deadlift'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-snatch-grip-deadlift', 'Snatch Grip Deadlift', 'Peso muerto con agarre de arrancada', 'strength', 'intermediate', ARRAY['barbell']::text[], ARRAY['lower back']::text[], ARRAY['hamstrings','glutes','traps']::text[], 'Take a wide grip on a barbell on the floor. Drive through the legs keeping a flat back. Stand tall and lower slowly.', 'Toma una barra del suelo con agarre ancho. Empuja con las piernas con la espalda recta. Ponte erguido y baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Snatch Grip Deadlift'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-block-pull', 'Block Pull', 'Peso muerto desde bloques', 'strength', 'intermediate', ARRAY['barbell']::text[], ARRAY['lower back']::text[], ARRAY['glutes','hamstrings','traps']::text[], 'Set a barbell on blocks at knee height. Grip it with a flat back. Stand tall and lower under control.', 'Coloca una barra sobre bloques a la altura de las rodillas. Agárrala con la espalda recta. Ponte erguido y baja con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Block Pull'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-prone-press-up', 'Prone Press-Up', 'Extensión lumbar boca abajo', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['lower back']::text[], ARRAY['abdominals']::text[], 'Lie face down with hands beside your chest. Press up with your arms keeping hips down. Lower slowly.', 'Túmbate boca abajo con las manos junto al pecho. Empuja con los brazos manteniendo la cadera abajo. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Prone Press-Up'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-exercise-ball-back-extension', 'Exercise Ball Back Extension', 'Extensión de espalda sobre balón', 'strength', 'beginner', ARRAY['exercise ball']::text[], ARRAY['lower back']::text[], ARRAY['glutes']::text[], 'Lie face down over a ball with feet braced. Cross your arms and curl your torso down. Raise until your body is in line.', 'Túmbate boca abajo sobre un balón con los pies apoyados. Cruza los brazos y baja el torso. Sube hasta alinear el cuerpo.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Exercise Ball Back Extension'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-chest-supported-t-bar-row', 'Chest-Supported T-Bar Row', 'Remo en barra T apoyado en el pecho', 'strength', 'intermediate', ARRAY['machine']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Lie chest down on the pad and grip the handles. Pull the handles toward your torso squeezing the shoulder blades. Lower slowly.', 'Túmbate con el pecho sobre el cojín y agarra las asas. Tira de las asas hacia el torso juntando las escápulas. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Chest-Supported T-Bar Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-iso-lateral-machine-row', 'Iso-Lateral Machine Row', 'Remo unilateral en máquina de discos', 'strength', 'intermediate', ARRAY['machine']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Sit in the machine with the chest pad set. Pull one handle at a time toward your hips. Return slowly.', 'Siéntate en la máquina con el cojín del pecho ajustado. Tira de un asa cada vez hacia la cadera. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Iso-Lateral Machine Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-seal-row', 'Seal Row', 'Remo foca', 'strength', 'intermediate', ARRAY['barbell']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Lie face down on a high bench with a barbell hanging below. Row the bar to the bench. Lower under control.', 'Túmbate boca abajo en un banco alto con una barra colgando debajo. Rema la barra hacia el banco. Baja con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Seal Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-yates-row', 'Yates Row', 'Remo Yates', 'strength', 'intermediate', ARRAY['barbell']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Hold a barbell with an underhand grip and a torso angle near 45 degrees. Row the bar to your waist. Lower under control.', 'Sujeta una barra con agarre supino y el torso a unos 45 grados. Rema la barra hacia la cintura. Baja con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Yates Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-standing-single-arm-cable-row', 'Standing Single-Arm Cable Row', 'Remo a una mano de pie en polea', 'strength', 'beginner', ARRAY['cable']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Stand facing a mid-height pulley and grip the handle. Row it to your ribs squeezing the shoulder blade. Return slowly.', 'Colócate frente a una polea media y agarra el asa. Rema hacia las costillas apretando la escápula. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Standing Single-Arm Cable Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-cable-row-with-rope', 'Cable Row with Rope', 'Remo en polea con cuerda', 'strength', 'beginner', ARRAY['cable']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Sit at a low pulley with a rope attached. Pull the rope to your torso and spread the ends. Return slowly.', 'Siéntate en una polea baja con una cuerda. Tira de la cuerda hacia el torso separando los extremos. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Cable Row with Rope'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-wide-grip-seated-cable-row', 'Wide-Grip Seated Cable Row', 'Remo sentado en polea agarre ancho', 'strength', 'beginner', ARRAY['cable']::text[], ARRAY['middle back']::text[], ARRAY['lats','shoulders']::text[], 'Sit at a low pulley with a wide bar. Pull the bar to your lower chest with elbows flared. Return slowly.', 'Siéntate en una polea baja con una barra ancha. Tira de la barra hacia la parte baja del pecho con los codos abiertos. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Wide-Grip Seated Cable Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-close-grip-seated-cable-row', 'Close-Grip Seated Cable Row', 'Remo sentado en polea agarre cerrado', 'strength', 'beginner', ARRAY['cable']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Sit at a low pulley with a close-grip handle. Pull to your abdomen keeping elbows tight. Return slowly.', 'Siéntate en una polea baja con un agarre cerrado. Tira hacia el abdomen con los codos pegados. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Close-Grip Seated Cable Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-reverse-grip-cable-row', 'Reverse-Grip Cable Row', 'Remo en polea agarre supino', 'strength', 'beginner', ARRAY['cable']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Sit at a low pulley with an underhand grip on a bar. Pull to your waist. Return slowly.', 'Siéntate en una polea baja con agarre supino en una barra. Tira hacia la cintura. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Reverse-Grip Cable Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-standing-band-row', 'Standing Band Row', 'Remo de pie con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Anchor a band at chest height and step back for tension. Row the handles to your ribs. Return slowly.', 'Ancla una banda a la altura del pecho y retrocede para tensarla. Rema las asas hacia las costillas. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Standing Band Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-prone-incline-dumbbell-row', 'Prone Incline Dumbbell Row', 'Remo boca abajo en banco inclinado con mancuernas', 'strength', 'beginner', ARRAY['dumbbell']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Lie chest down on an incline bench holding dumbbells. Row both weights up with elbows high. Lower slowly.', 'Túmbate con el pecho sobre un banco inclinado sujetando mancuernas. Rema ambas pesas con los codos altos. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Prone Incline Dumbbell Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-wide-grip-australian-pull-up', 'Wide-Grip Australian Pull-Up', 'Remo australiano agarre ancho', 'strength', 'intermediate', ARRAY['body only']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Hang under a low bar with a wide grip and straight body. Pull your chest to the bar. Lower slowly.', 'Cuélgate bajo una barra baja con agarre ancho y el cuerpo recto. Lleva el pecho a la barra. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Wide-Grip Australian Pull-Up'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-feet-elevated-inverted-row', 'Feet-Elevated Inverted Row', 'Remo invertido con pies elevados', 'strength', 'intermediate', ARRAY['body only']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Hang under a bar with your feet on a bench. Pull your chest to the bar keeping the body straight. Lower slowly.', 'Cuélgate bajo una barra con los pies sobre un banco. Lleva el pecho a la barra con el cuerpo recto. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Feet-Elevated Inverted Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-landmine-row', 'Landmine Row', 'Remo en landmine', 'strength', 'intermediate', ARRAY['barbell']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Straddle a landmine bar with a V-handle under the end. Hinge and row the bar to your chest. Lower slowly.', 'Colócate a horcajadas sobre una barra landmine con un asa en V bajo el extremo. Inclínate y rema hacia el pecho. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Landmine Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-thoracic-extension-over-foam-roller', 'Thoracic Extension over Foam Roller', 'Extensión torácica sobre rodillo de espuma', 'stretching', 'beginner', ARRAY['foam roll']::text[], ARRAY['middle back']::text[], ARRAY[]::text[], 'Lie with a foam roller under your upper back and hands behind your head. Extend your spine over the roller. Move up and down slowly.', 'Túmbate con un rodillo bajo la parte alta de la espalda y las manos tras la cabeza. Extiende la columna sobre el rodillo. Desplázate arriba y abajo despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Thoracic Extension over Foam Roller'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-thread-the-needle', 'Thread the Needle', 'Pasar el hilo por la aguja', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['middle back']::text[], ARRAY['shoulders']::text[], 'Start on hands and knees. Slide one arm under your body palm up. Rest your shoulder on the floor and hold.', 'Empieza a cuatro apoyos. Desliza un brazo bajo el cuerpo con la palma hacia arriba. Apoya el hombro en el suelo y mantén.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Thread the Needle'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-scapular-retraction', 'Scapular Retraction', 'Retracción escapular', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['middle back']::text[], ARRAY['traps']::text[], 'Stand or sit tall with arms by your sides. Squeeze your shoulder blades together and down. Hold and release.', 'Ponte de pie o siéntate erguido con los brazos a los lados. Junta las escápulas hacia abajo. Mantén y suelta.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Scapular Retraction'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-barbell-power-shrug', 'Barbell Power Shrug', 'Encogimientos explosivos con barra', 'strength', 'intermediate', ARRAY['barbell']::text[], ARRAY['traps']::text[], ARRAY['calves','glutes']::text[], 'Hold a barbell at mid-thigh with a slight knee bend. Extend your hips and shrug explosively. Lower under control.', 'Sujeta una barra a media altura del muslo con las rodillas algo flexionadas. Extiende la cadera y encoge los hombros con fuerza. Baja con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Barbell Power Shrug'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-kettlebell-shrug', 'Kettlebell Shrug', 'Encogimientos con pesa rusa', 'strength', 'beginner', ARRAY['kettlebells']::text[], ARRAY['traps']::text[], ARRAY['forearms']::text[], 'Hold a kettlebell in each hand at your sides. Shrug your shoulders straight up. Lower slowly.', 'Sujeta una pesa rusa en cada mano a los lados. Encoge los hombros hacia arriba. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Kettlebell Shrug'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-trap-bar-shrug', 'Trap Bar Shrug', 'Encogimientos con barra hexagonal', 'strength', 'beginner', ARRAY['barbell']::text[], ARRAY['traps']::text[], ARRAY['forearms']::text[], 'Stand inside a trap bar and hold the handles. Shrug your shoulders straight up. Lower slowly.', 'Colócate dentro de una barra hexagonal y agarra las asas. Encoge los hombros hacia arriba. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Trap Bar Shrug'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-machine-shrug', 'Machine Shrug', 'Encogimientos en máquina', 'strength', 'beginner', ARRAY['machine']::text[], ARRAY['traps']::text[], ARRAY['forearms']::text[], 'Stand in the shrug machine and grip the handles. Shrug your shoulders up. Lower slowly.', 'Colócate en la máquina de encogimientos y agarra las asas. Encoge los hombros hacia arriba. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Machine Shrug'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-prone-incline-dumbbell-shrug', 'Prone Incline Dumbbell Shrug', 'Encogimientos boca abajo en banco inclinado con mancuernas', 'strength', 'intermediate', ARRAY['dumbbell']::text[], ARRAY['traps']::text[], ARRAY['middle back']::text[], 'Lie chest down on an incline bench holding dumbbells. Shrug your shoulder blades back and together. Lower slowly.', 'Túmbate con el pecho sobre un banco inclinado sujetando mancuernas. Lleva las escápulas atrás y juntas. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Prone Incline Dumbbell Shrug'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-single-arm-dumbbell-shrug', 'Single-Arm Dumbbell Shrug', 'Encogimientos a una mano con mancuerna', 'strength', 'beginner', ARRAY['dumbbell']::text[], ARRAY['traps']::text[], ARRAY['forearms']::text[], 'Hold a dumbbell in one hand at your side. Shrug that shoulder straight up. Lower slowly and switch sides.', 'Sujeta una mancuerna en una mano a un lado. Encoge ese hombro hacia arriba. Baja despacio y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Single-Arm Dumbbell Shrug'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-band-shrug', 'Band Shrug', 'Encogimientos con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['traps']::text[], ARRAY[]::text[], 'Stand on a band holding the handles at your sides. Shrug your shoulders up. Lower slowly.', 'Pisa una banda sujetando las asas a los lados. Encoge los hombros hacia arriba. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Band Shrug'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-prone-y-raise', 'Prone Y Raise', 'Elevación en Y boca abajo', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['traps']::text[], ARRAY['shoulders','middle back']::text[], 'Lie face down with arms overhead in a Y shape. Lift your arms off the floor with thumbs up. Lower slowly.', 'Túmbate boca abajo con los brazos sobre la cabeza en forma de Y. Eleva los brazos con los pulgares arriba. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Prone Y Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-prone-t-raise', 'Prone T Raise', 'Elevación en T boca abajo', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['traps']::text[], ARRAY['shoulders','middle back']::text[], 'Lie face down with arms out to the sides in a T shape. Lift your arms squeezing the shoulder blades. Lower slowly.', 'Túmbate boca abajo con los brazos en cruz. Eleva los brazos apretando las escápulas. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Prone T Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-dumbbell-high-pull', 'Dumbbell High Pull', 'Tirón alto con mancuernas', 'strength', 'intermediate', ARRAY['dumbbell']::text[], ARRAY['traps']::text[], ARRAY['shoulders','glutes']::text[], 'Hold dumbbells in front of your thighs. Extend your hips and pull the weights up with elbows high. Lower under control.', 'Sujeta mancuernas frente a los muslos. Extiende la cadera y tira de las pesas con los codos altos. Baja con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Dumbbell High Pull'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-rack-shrug', 'Rack Shrug', 'Encogimientos desde rack', 'strength', 'intermediate', ARRAY['barbell']::text[], ARRAY['traps']::text[], ARRAY['forearms']::text[], 'Set a barbell in a rack at knee height. Lift it and stand tall. Shrug your shoulders up and lower slowly.', 'Coloca una barra en un rack a la altura de las rodillas. Levántala y ponte erguido. Encoge los hombros y baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Rack Shrug'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-overhead-plate-carry', 'Overhead Plate Carry', 'Paseo con disco sobre la cabeza', 'strength', 'intermediate', ARRAY['other']::text[], ARRAY['traps']::text[], ARRAY['shoulders','abdominals']::text[], 'Hold a plate overhead with arms straight. Walk a set distance with ribs down. Lower the plate with control.', 'Sostén un disco sobre la cabeza con los brazos estirados. Camina una distancia fija con las costillas abajo. Baja el disco con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Overhead Plate Carry'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-upper-trap-stretch', 'Upper Trap Stretch', 'Estiramiento de trapecio superior', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['traps']::text[], ARRAY['neck']::text[], 'Sit tall and tilt your head toward one shoulder. Rest a hand on your head for a gentle pull. Hold and switch sides.', 'Siéntate erguido e inclina la cabeza hacia un hombro. Apoya una mano en la cabeza para un tirón suave. Mantén y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Upper Trap Stretch'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-trapezius-smr', 'Trapezius-SMR', 'Liberación miofascial del trapecio', 'stretching', 'beginner', ARRAY['foam roll']::text[], ARRAY['traps']::text[], ARRAY[]::text[], 'Place a foam roller or ball under your upper trapezius. Roll slowly over tender areas. Pause on tight spots and breathe.', 'Coloca un rodillo o pelota bajo el trapecio superior. Rueda despacio sobre las zonas sensibles. Haz una pausa en los puntos tensos y respira.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Trapezius-SMR'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-scapular-shrug-hang', 'Scapular Shrug Hang', 'Encogimientos escapulares colgado', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['traps']::text[], ARRAY['lats','forearms']::text[], 'Hang from a bar with straight arms. Depress and elevate your shoulder blades without bending the elbows. Repeat slowly.', 'Cuélgate de una barra con los brazos estirados. Baja y sube las escápulas sin flexionar los codos. Repite despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Scapular Shrug Hang'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-single-leg-machine-seated-calf-raise', 'Single-Leg Machine Seated Calf Raise', 'Elevación de gemelos sentado a una pierna en máquina', 'strength', 'intermediate', ARRAY['machine']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Sit in the machine with one foot on the platform. Press up through the ball of the foot. Lower slowly.', 'Siéntate en la máquina con un pie en la plataforma. Empuja con la parte delantera del pie. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Single-Leg Machine Seated Calf Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-smith-machine-seated-calf-raise', 'Smith Machine Seated Calf Raise', 'Elevación de gemelos sentado en máquina Smith', 'strength', 'intermediate', ARRAY['machine']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Sit on a bench under a Smith bar with feet on a plate. Rest the bar on your thighs. Raise your heels and lower slowly.', 'Siéntate en un banco bajo la barra Smith con los pies sobre un disco. Apoya la barra en los muslos. Sube los talones y baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Smith Machine Seated Calf Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-single-leg-press-calf-raise', 'Single-Leg Press Calf Raise', 'Elevación de gemelos a una pierna en prensa', 'strength', 'intermediate', ARRAY['machine']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Sit in the leg press with one forefoot on the platform. Push through the toes extending the ankle. Return slowly.', 'Siéntate en la prensa con un antepié en la plataforma. Empuja con las puntas extendiendo el tobillo. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Single-Leg Press Calf Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-wall-tibialis-raise', 'Wall Tibialis Raise', 'Elevación de tibial contra la pared', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Lean against a wall with feet forward. Pull your toes up toward your shins. Lower slowly.', 'Apóyate en una pared con los pies adelantados. Sube las puntas hacia las espinillas. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Wall Tibialis Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-tibialis-bar-raise', 'Tibialis Bar Raise', 'Elevación de tibial con barra tibial', 'strength', 'intermediate', ARRAY['other']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Stand on a tibia bar with your heels on the floor. Pull your toes up against the weight. Lower slowly.', 'Ponte sobre una barra tibial con los talones en el suelo. Sube las puntas contra el peso. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Tibialis Bar Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-seated-dumbbell-tibialis-raise', 'Seated Dumbbell Tibialis Raise', 'Elevación de tibial sentado con mancuerna', 'strength', 'beginner', ARRAY['dumbbell']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Sit with a dumbbell held between your feet. Lift your toes toward your shins. Lower slowly.', 'Siéntate con una mancuerna entre los pies. Sube las puntas hacia las espinillas. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Seated Dumbbell Tibialis Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-band-tibialis-raise', 'Band Tibialis Raise', 'Elevación de tibial con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Anchor a band and loop it over your forefoot. Pull your toes toward your shin against the band. Return slowly.', 'Ancla una banda y pásala por el antepié. Sube las puntas hacia la espinilla contra la banda. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Band Tibialis Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-toe-walk', 'Toe Walk', 'Caminata de puntillas', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Rise onto the balls of your feet. Walk forward staying high on your toes. Keep your posture tall.', 'Sube sobre las puntas de los pies. Camina hacia delante manteniéndote en puntillas. Mantén la postura erguida.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Toe Walk'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-heel-walk', 'Heel Walk', 'Caminata de talones', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Lift your toes off the floor. Walk forward on your heels. Keep your posture tall.', 'Levanta las puntas del suelo. Camina hacia delante sobre los talones. Mantén la postura erguida.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Heel Walk'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-ankle-hops', 'Ankle Hops', 'Saltos de tobillo', 'plyometrics', 'beginner', ARRAY['body only']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Stand tall with soft knees. Hop using only your ankles with quick contacts. Land softly and repeat.', 'Ponte erguido con las rodillas suaves. Salta usando solo los tobillos con contactos rápidos. Aterriza suave y repite.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Ankle Hops'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-eccentric-single-leg-calf-raise', 'Eccentric Single-Leg Calf Raise', 'Elevación excéntrica de gemelos a una pierna', 'strength', 'intermediate', ARRAY['body only']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Stand on a step and rise on both feet. Shift to one leg and lower over three to four seconds. Repeat and switch legs.', 'Ponte en un escalón y sube con ambos pies. Pasa a una pierna y baja en tres o cuatro segundos. Repite y cambia de pierna.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Eccentric Single-Leg Calf Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-bent-knee-calf-raise', 'Bent-Knee Calf Raise', 'Elevación de gemelos con rodillas flexionadas', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Stand with knees bent about 30 degrees. Raise your heels keeping the knee angle. Lower slowly.', 'Ponte con las rodillas flexionadas unos 30 grados. Sube los talones manteniendo el ángulo. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Bent-Knee Calf Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-kettlebell-calf-raise', 'Kettlebell Calf Raise', 'Elevación de gemelos con pesa rusa', 'strength', 'beginner', ARRAY['kettlebells']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Hold a kettlebell at your side while standing on a step. Rise onto your toes. Lower into a stretch.', 'Sujeta una pesa rusa a un lado sobre un escalón. Sube sobre las puntas. Baja hasta estirar.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Kettlebell Calf Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-seated-band-calf-raise', 'Seated Band Calf Raise', 'Elevación de gemelos sentado con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Sit with legs extended and a band around your forefeet. Point your toes against the band. Return slowly.', 'Siéntate con las piernas estiradas y una banda en los antepiés. Extiende los pies contra la banda. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Seated Band Calf Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-downward-dog-calf-stretch', 'Downward Dog Calf Stretch', 'Estiramiento de gemelos en perro boca abajo', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['calves']::text[], ARRAY['hamstrings']::text[], 'Start in a downward dog position. Press one heel toward the floor while bending the other knee. Hold and switch.', 'Empieza en la postura del perro boca abajo. Empuja un talón al suelo mientras flexionas la otra rodilla. Mantén y cambia.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Downward Dog Calf Stretch'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-plantar-fascia-stretch', 'Plantar Fascia Stretch', 'Estiramiento de la fascia plantar', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Sit and cross one foot over the opposite knee. Pull your toes back toward your shin. Hold and switch.', 'Siéntate y cruza un pie sobre la rodilla contraria. Tira de los dedos hacia la espinilla. Mantén y cambia.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Plantar Fascia Stretch'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-ankle-alphabet', 'Ankle Alphabet', 'Abecedario con el tobillo', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Sit with one leg lifted. Draw each letter of the alphabet with your toes. Switch legs.', 'Siéntate con una pierna elevada. Dibuja cada letra del abecedario con los dedos del pie. Cambia de pierna.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Ankle Alphabet'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-tibialis-anterior-stretch', 'Tibialis Anterior Stretch', 'Estiramiento de tibial anterior', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['calves']::text[], ARRAY[]::text[], 'Kneel with the tops of your feet on the floor. Sit back gently onto your heels. Hold and breathe.', 'Arrodíllate con el empeine apoyado en el suelo. Siéntate suavemente sobre los talones. Mantén y respira.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Tibialis Anterior Stretch'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-hanging-knee-raise', 'Hanging Knee Raise', 'Elevación de rodillas colgado', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['abdominals']::text[], ARRAY['forearms']::text[], 'Hang from a bar with straight arms. Raise your knees toward your chest. Lower slowly without swinging.', 'Cuélgate de una barra con los brazos estirados. Sube las rodillas hacia el pecho. Baja despacio sin balancearte.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Hanging Knee Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-machine-hip-thrust', 'Machine Hip Thrust', 'Empuje de cadera en máquina', 'strength', 'beginner', ARRAY['machine']::text[], ARRAY['glutes']::text[], ARRAY['hamstrings']::text[], 'Sit in the machine with the pad over your hips. Drive your hips up squeezing the glutes. Lower slowly.', 'Siéntate en la máquina con el cojín sobre las caderas. Empuja la cadera hacia arriba apretando los glúteos. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Machine Hip Thrust'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-reverse-hack-squat', 'Reverse Hack Squat', 'Sentadilla hack inversa', 'strength', 'intermediate', ARRAY['machine']::text[], ARRAY['glutes']::text[], ARRAY['quadriceps','hamstrings']::text[], 'Face the pad of a hack machine with your chest on it. Squat down with feet high on the platform. Drive up squeezing the glutes.', 'Colócate de cara al cojín de una máquina hack con el pecho apoyado. Baja en sentadilla con los pies altos en la plataforma. Sube apretando los glúteos.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Reverse Hack Squat'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-sissy-squat', 'Sissy Squat', 'Sentadilla sissy', 'strength', 'intermediate', ARRAY['body only']::text[], ARRAY['quadriceps']::text[], ARRAY[]::text[], 'Hold a support and rise onto your toes. Lean back while bending your knees forward. Return by extending the knees.', 'Sujétate a un soporte y sube sobre las puntas. Inclínate atrás mientras las rodillas avanzan. Vuelve extendiendo las rodillas.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Sissy Squat'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-chest-supported-rear-delt-row', 'Chest-Supported Rear Delt Row', 'Remo para deltoides posterior apoyado en el pecho', 'strength', 'beginner', ARRAY['dumbbell']::text[], ARRAY['shoulders']::text[], ARRAY['middle back','traps']::text[], 'Lie chest down on an incline bench with dumbbells. Row with elbows flared out to the sides. Lower slowly.', 'Túmbate con el pecho sobre un banco inclinado con mancuernas. Rema con los codos abiertos hacia los lados. Baja despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Chest-Supported Rear Delt Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-archer-push-up', 'Archer Push-Up', 'Flexiones arquero', 'strength', 'expert', ARRAY['body only']::text[], ARRAY['chest']::text[], ARRAY['triceps','shoulders']::text[], 'Take a wide push-up stance. Lower toward one hand while the other arm stays straight. Push up and alternate.', 'Adopta una posición de flexión ancha. Baja hacia una mano con el otro brazo estirado. Sube y alterna.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Archer Push-Up'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-deep-squat-hold', 'Deep Squat Hold', 'Sentadilla profunda sostenida', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['quadriceps']::text[], ARRAY['glutes','adductors']::text[], 'Stand with feet slightly wider than shoulders. Lower into a deep squat with chest tall. Hold and breathe.', 'Ponte con los pies algo más anchos que los hombros. Baja a una sentadilla profunda con el pecho alto. Mantén y respira.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Deep Squat Hold'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-scorpion-stretch', 'Scorpion Stretch', 'Estiramiento escorpión', 'stretching', 'intermediate', ARRAY['body only']::text[], ARRAY['lower back']::text[], ARRAY['glutes','chest']::text[], 'Lie face down with arms out. Swing one heel up and across to the opposite hand. Return and alternate.', 'Túmbate boca abajo con los brazos abiertos. Lleva un talón arriba y cruzando hacia la mano contraria. Vuelve y alterna.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Scorpion Stretch'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-side-lying-banded-leg-raise', 'Side-Lying Banded Leg Raise', 'Elevación lateral de pierna tumbado con banda', 'strength', 'beginner', ARRAY['bands']::text[], ARRAY['abductors']::text[], ARRAY['glutes']::text[], 'Lie on your side with a band above the knees. Lift the top leg straight up against the band. Lower slowly and switch sides.', 'Túmbate de lado con una banda sobre las rodillas. Eleva la pierna superior estirada contra la banda. Baja despacio y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Side-Lying Banded Leg Raise'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-band-crab-walk', 'Band Crab Walk', 'Caminata de cangrejo con banda', 'strength', 'intermediate', ARRAY['bands']::text[], ARRAY['abductors']::text[], ARRAY['glutes','quadriceps']::text[], 'Place a band around your ankles and sit into a half squat. Step diagonally sideways keeping tension. Alternate directions.', 'Coloca una banda en los tobillos y baja a media sentadilla. Da pasos laterales en diagonal manteniendo la tensión. Alterna las direcciones.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Band Crab Walk'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-side-lunge-stretch', 'Side Lunge Stretch', 'Estiramiento en zancada lateral', 'stretching', 'beginner', ARRAY['body only']::text[], ARRAY['adductors']::text[], ARRAY['glutes']::text[], 'Stand with a wide stance and shift to one side bending that knee. Keep the other leg straight with the foot flat. Hold and switch sides.', 'Ponte con una postura ancha y carga un lado flexionando esa rodilla. Mantén la otra pierna estirada con el pie plano. Mantén y cambia de lado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Side Lunge Stretch'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-dumbbell-cossack-squat', 'Dumbbell Cossack Squat', 'Sentadilla cosaca con mancuerna', 'strength', 'intermediate', ARRAY['dumbbell']::text[], ARRAY['adductors']::text[], ARRAY['glutes','quadriceps']::text[], 'Hold a dumbbell at your chest in a wide stance. Shift to one side and squat deep with the other leg straight. Return and alternate.', 'Sujeta una mancuerna al pecho con postura ancha. Carga un lado y baja profundo con la otra pierna estirada. Vuelve y alterna.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Dumbbell Cossack Squat'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-landmine-good-morning', 'Landmine Good Morning', 'Buenos días en landmine', 'strength', 'intermediate', ARRAY['barbell']::text[], ARRAY['lower back']::text[], ARRAY['hamstrings','glutes']::text[], 'Hold the end of a landmine bar at your chest. Hinge at the hips with a flat back. Drive hips forward to stand.', 'Sujeta el extremo de una barra landmine al pecho. Inclínate desde la cadera con la espalda recta. Lleva la cadera adelante para subir.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Landmine Good Morning'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-hip-hinge-dowel-drill', 'Hip Hinge Dowel Drill', 'Ejercicio de bisagra de cadera con palo', 'strength', 'beginner', ARRAY['other']::text[], ARRAY['lower back']::text[], ARRAY['hamstrings','glutes']::text[], 'Hold a dowel along your spine touching head, upper back and hips. Push your hips back while keeping contact. Return to standing.', 'Sujeta un palo a lo largo de la columna tocando cabeza, espalda y cadera. Lleva la cadera atrás manteniendo el contacto. Vuelve a la posición de pie.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Hip Hinge Dowel Drill'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-weighted-plank', 'Weighted Plank', 'Plancha con peso', 'strength', 'intermediate', ARRAY['other']::text[], ARRAY['abdominals']::text[], ARRAY['shoulders','lower back']::text[], 'Get into a forearm plank and have a plate placed on your back. Keep your body in a straight line. Hold for time.', 'Adopta una plancha sobre antebrazos y coloca un disco en la espalda. Mantén el cuerpo en línea recta. Aguanta el tiempo marcado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Weighted Plank'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-suspended-hamstring-curl', 'Suspended Hamstring Curl', 'Curl de isquiotibiales suspendido', 'strength', 'intermediate', ARRAY['other']::text[], ARRAY['hamstrings']::text[], ARRAY['glutes']::text[], 'Lie on your back with heels in suspension straps and hips lifted. Curl your heels toward your glutes. Extend slowly.', 'Túmbate boca arriba con los talones en las correas y la cadera elevada. Lleva los talones hacia los glúteos. Extiende despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Suspended Hamstring Curl'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-wall-sit', 'Wall Sit', 'Sentadilla isométrica en pared', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['quadriceps']::text[], ARRAY['glutes']::text[], 'Lean your back against a wall. Slide down until thighs are parallel. Hold for time.', 'Apoya la espalda en una pared. Deslízate hasta que los muslos queden paralelos. Mantén el tiempo marcado.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Wall Sit'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-z-press', 'Z-Press', 'Press Z', 'strength', 'expert', ARRAY['barbell']::text[], ARRAY['shoulders']::text[], ARRAY['triceps','abdominals']::text[], 'Sit on the floor with legs straight holding a barbell at your shoulders. Press the bar overhead without leaning. Lower with control.', 'Siéntate en el suelo con las piernas estiradas sujetando una barra a los hombros. Empuja la barra sobre la cabeza sin inclinarte. Baja con control.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Z-Press'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-lateral-lunge', 'Lateral Lunge', 'Zancada lateral', 'strength', 'beginner', ARRAY['body only']::text[], ARRAY['adductors']::text[], ARRAY['glutes','quadriceps']::text[], 'Stand tall and take a big step to the side. Sit back into that hip keeping the other leg straight. Push back to the start and alternate.', 'Ponte erguido y da un paso largo hacia el lado. Siéntate sobre esa cadera con la otra pierna estirada. Empuja para volver y alterna.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Lateral Lunge'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-wide-grip-machine-row', 'Wide-Grip Machine Row', 'Remo en máquina agarre ancho', 'strength', 'beginner', ARRAY['machine']::text[], ARRAY['middle back']::text[], ARRAY['lats','shoulders']::text[], 'Sit with your chest on the pad and take the wide handles. Pull back with elbows flared. Return slowly.', 'Siéntate con el pecho en el cojín y agarra las asas anchas. Tira hacia atrás con los codos abiertos. Vuelve despacio.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Wide-Grip Machine Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-incline-bench-single-arm-dumbbell-row', 'Incline Bench Single-Arm Dumbbell Row', 'Remo a una mano en banco inclinado con mancuerna', 'strength', 'beginner', ARRAY['dumbbell']::text[], ARRAY['middle back']::text[], ARRAY['lats','biceps']::text[], 'Lie chest down on an incline bench holding a dumbbell in one hand. Row the weight toward your hip. Lower slowly and switch arms.', 'Túmbate con el pecho sobre un banco inclinado sujetando una mancuerna. Rema el peso hacia la cadera. Baja despacio y cambia de brazo.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Incline Bench Single-Arm Dumbbell Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-dumbbell-pendlay-row', 'Dumbbell Pendlay Row', 'Remo Pendlay con mancuernas', 'strength', 'intermediate', ARRAY['dumbbell']::text[], ARRAY['middle back']::text[], ARRAY['lats','lower back']::text[], 'Hold dumbbells on the floor with your back parallel to the ground. Row both weights to your ribs. Lower them to the floor each rep.', 'Sujeta mancuernas en el suelo con la espalda paralela al suelo. Rema ambas pesas hacia las costillas. Bájalas al suelo en cada repetición.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Dumbbell Pendlay Row'));
INSERT INTO exercises (user_id, source, source_id, name_en, name_es, category, level, equipment, primary_muscles, secondary_muscles, instructions_en, instructions_es, images, license, attribution) SELECT NULL, 'forja', 'forja-adductor-slider-slide', 'Adductor Slider Slide', 'Deslizamiento de aductores con deslizador', 'strength', 'beginner', ARRAY['other']::text[], ARRAY['adductors']::text[], ARRAY['glutes']::text[], 'Lie on your back with knees bent and heels on sliders. Slide both heels apart as far as comfortable. Squeeze your inner thighs to bring them back.', 'Túmbate boca arriba con las rodillas flexionadas y los talones sobre deslizadores. Separa ambos talones hasta donde puedas con comodidad. Aprieta los muslos internos para volver.', ARRAY[]::text[], 'Contenido propio', 'Forja' WHERE NOT EXISTS (SELECT 1 FROM exercises x WHERE x.user_id IS NULL AND lower(x.name_en) = lower('Adductor Slider Slide'));
